body #attract .arcover .aor + .aor{ margin-top:calc(var(--sp-1) * var(--attz,1)); }
/* v28.xx (cw-party-over3), his order 2026-10-18 (UI step 3, party screens 52 and 55): the critic scored the run over card 2 ("a small box floating in a black void,
   Press any button is plain text 400px under the card, no primary action"). While the run over card is up the screen is one centred column: the card (840px x scale, as it was),
   a 24px gap, then Press any button as a real button (1px accent line, accent at 14 percent, 8px radius, 16 and 48px padding). The prompt keeps its words and its
   32px size; only where it sits and its plate change. */
body #attract[style*="block"]:has(.arcover[style*="block"]){ display:flex !important; flex-direction:column; align-items:center; justify-content:center; gap:calc(var(--sp-4) * var(--attz,1)); }
body #attract[style*="block"]:has(.arcover[style*="block"]) > video{ position:absolute; left:0; top:0; }
body #attract[style*="block"]:has(.arcover[style*="block"]) .arcover{ position:relative; left:auto; top:auto; transform:none; order:1; }
body #attract[style*="block"]:has(.arcover[style*="block"]) .attpress{ position:relative; left:auto; right:auto; bottom:auto; order:2; width:max-content; padding:calc(var(--sp-2) * var(--attz,1)) calc(var(--sp-5) * var(--attz,1)); border:1px solid var(--acc); border-radius:var(--rad); background:color-mix(in srgb, var(--acc) 14%, transparent); }

check:
{v:'VER',what:'while the run over card is up, Press any button is a plate under the card (a 1px accent line, in the same centred column, under 60px below it), not loose text pinned at the bottom (critic: card floats in a void, prompt detached; screens 52 55)',
 run:function(){
   if(typeof arcadeAttEl!=='function'||typeof attEl!=='function') return 'SKIP: no arcade attract here';
   var d, oc, wasDisp, ap, ar, cr, cs, res=null;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     oc=arcadeAttEl('arcover'); oc.style.display='block';
     ap=d.querySelector('.attpress'); cs=getComputedStyle(ap);
     ar=ap.getBoundingClientRect(); cr=oc.getBoundingClientRect();
     if(cs.position!=='relative') res='Press any button is '+cs.position+', not in the card column';
     else if(parseFloat(cs.borderTopWidth)<1) res='Press any button has no plate line';
     else if(ar.top-cr.bottom<0||ar.top-cr.bottom>80) res='Press any button sits '+Math.round(ar.top-cr.bottom)+'px under the card, not within 80px';
     else if(Math.abs((ar.left+ar.right)/2-(cr.left+cr.right)/2)>3) res='Press any button is not centred under the card';
     else if(Math.abs((cr.top+ar.bottom)/2-d.getBoundingClientRect().height/2)>60) res='the card and button sit at '+Math.round((cr.top+ar.bottom)/2)+'px, not about the middle of the screen ('+Math.round(d.getBoundingClientRect().height/2)+')';
     return res;
   } finally {
     try{ oc.style.display='none'; d.style.display=wasDisp; }catch(_f){}
   }
 }},
